   epoch=row.method_epoch;seed_condition=row.buy_breadth_pct120>=.8 and (g.loc[i-1,"buy_breadth_pct120"]<.8 if i>0 and g.loc[i-1,"method_epoch"]==row.method_epoch and pd.notna(g.loc[i-1,"buy_breadth_pct120"]) else False) and row.persistent_buy_count>=3 and row.sector_large_net_rate>0
   if state=="DORMANT":
    if seed_condition:state="ACCUMULATION_SEED";seed=i;diffusion=None;broad=None;wave_id=f"{row.trade_date.date()}|{sector}"
    continue
   if state=="ACCUMULATION_SEED":
    last3=g.loc[max(seed,i-2):i];condition=len(last3)==3 and (last3.buy_breadth_pct120>=.8).all() and row.new_buy_rate_pct120>=.7 and row.sector_large_net_rate>0 and row.buy_breadth>row.sell_breadth
    if condition:state="BUY_DIFFUSION";diffusion=i;low_buy=0;negative_flow=0
